.chat-detail-screen .voice-msg-them::before,
.chat-detail-screen .voice-msg-them::after,
.chat-detail-screen .voice-msg-me::before,
.chat-detail-screen .voice-msg-me::after {
  content: none !important;
  display: none !important;
}

.chat-detail-screen .voice-download-btn {
  display: none !important;
}

/* 语音消息总容器 */
.chat-detail-screen .voice-msg-them,
