   ========================================================================== */

/* 语音转文字触发点击热区 */
.chat-detail-screen .voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 22px !important;
  right: 0 !important;
  height: 22px !important;
  width: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  font-size: 0 !important;
  color: transparent !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  z-index: 5 !important;
}

.chat-detail-screen .voice-transcription-toggle *,
.chat-detail-screen .voice-transcription-toggle::before,
.chat-detail-screen .voice-transcription-toggle::after {
  content: none !important;
  display: none !important;
}

/* 展开后的语音转文字面板 */
.chat-detail-screen .voice-transcription {
  position: relative !important;
  margin-top: -1px !important;
  margin-left: 14px !important;
  margin-right: 4px !important;
  padding: 6px 11px 13px 10px !important;
  border-radius: 0 0 8px 8px !important;
  font-size: 11px !important;
  line-height: 1.4 !important;
  font-weight: 500 !important;
  word-break: break-word !important;
