  color: #363C40 !important;
}

.chat-detail-screen .msg-me .voice-transcription {
  background: linear-gradient(180deg, #F0E2EA 0%, #FFFFFF 22%, #FAF4F7 100%) !important;
  border: 0.95px solid #9A8690 !important;
  border-top: 0.8px dashed #B09CA6 !important;
  color: #463A40 !important;
}

/* 语音转文字面板右下角小标签 */
.chat-detail-screen .voice-transcription::after {
  content: '♪ voice note' !important; /* ✏️【可修改文字】：语音转文字卡片右下角的装饰英文 */
  position: absolute !important;
  right: 7px !important;
  bottom: 2.5px !important;
  width: auto !important;
  height: auto !important;
  background: none !important;
  font-family: 'Georgia', serif !important;
  font-style: italic !important;
  font-size: 7.5px !important;
  color: #8E7C86 !important;
  pointer-events: none !important;
  opacity: 0.9 !important;
}

/* 隐藏气泡内部原生翻译分割线与按钮，启用独立字幕式翻译 */
.chat-detail-screen :is(.msg-translation-btn, .translation-divider, hr, [class*="translation-sep"], .msg-plain .msg-translation-wrapper) {
  display: none !important;
}

@keyframes subtitleLiveReveal {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* 独立外挂翻译字幕容器 */
.chat-detail-screen .msg-translation-detached {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: relative !important;
  width: fit-content !important;
  max-width: 64vw !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin-top: 3px !important;
  margin-bottom: 2px !important;
  pointer-events: none !important;
  z-index: 6 !important;
  animation: subtitleLiveReveal 0.35s cubic-bezier(0.16, 1, 0.3, 1) both !important;
}

.chat-detail-screen .msg-bubble-wrapper:has([class*="voice"]) .msg-translation-detached {
