}

/* 翻译字幕描边字体样式 */
.chat-detail-screen .msg-translation-detached-content {
  display: block !important;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif !important;
  font-size: 12px !important;
  font-weight: 750 !important;
  line-height: 1.35 !important;
  word-break: break-word !important;
  white-space: pre-wrap !important;
  background: transparent !important;
  border: none !important;
  color: #FFFFFF !important;
  -webkit-text-fill-color: #FFFFFF !important;
  text-shadow:
    -1px -1px 0 #3E464D,
     0px -1px 0 #3E464D,
     1px -1px 0 #3E464D,
    -1px  0px 0 #3E464D,
     1px  0px 0 #3E464D,
    -1px  1px 0 #3E464D,
     0px  1px 0 #3E464D,
     1px  1px 0 #3E464D !important;
}

.chat-detail-screen .msg-them .msg-translation-detached {
  margin-left: 2px !important;
  margin-right: auto !important;
  text-align: left !important;
}

.chat-detail-screen .msg-me .msg-translation-detached {
  margin-left: auto !important;
  margin-right: 2px !important;
  text-align: right !important;
}
